import SwiftUI
import CleanerCore
import AppKit

@main struct MacAICleanerApp: App { var body: some Scene { WindowGroup { ContentView() } } }
struct ContentView: View {
 @State private var report: ScanReport?; @State private var scanning=false; @State private var status="准备开始一次只读扫描"; @State private var currentTool=""; @State private var showMemory=false; @State private var showLarge=false; @State private var showSettings=false
 var body: some View { NavigationSplitView { Sidebar(report: report, scanning: scanning, status: "准备开始一次只读扫描", currentTool: "", active: showSettings ? "settings" : showMemory ? "memory" : showLarge ? "large" : "scan", action: { showMemory = false; showLarge = false; showSettings = false; report = nil }, memoryAction: { showMemory = true; showLarge = false; showSettings = false }, largeAction: { showLarge = true; showMemory = false; showSettings = false }, settingsAction: { showSettings = true; showMemory = false; showLarge = false }) } detail: { if showSettings { SettingsView() } else if showMemory { MemoryView() } else if showLarge { LargeFilesStandalone() } else if scanning { ScanProgressView(tool: currentTool, status: status, start: startScan) } else if let report { Dashboard2(report: report) } else { ScanProgressView(tool: "", status: "准备开始一次只读扫描", start: startScan) } }.frame(minWidth:1080,minHeight:700) }
 private func startScan() { guard !scanning else{return}; scanning=true; status="正在读取文件元数据…"; Task.detached { let result=Scanner().scan(progress:{ name in Task { @MainActor in currentTool=name; status="正在检查 \(name)…" } }); await MainActor.run { report=result; scanning=false; currentTool=""; status="扫描完成 · 未执行删除" } } }
}
struct Sidebar: View { let report:ScanReport?; let scanning:Bool; let status:String; let currentTool:String; let active:String; let action:()->Void; let memoryAction:()->Void; let largeAction:()->Void; let settingsAction:()->Void
 var body: some View { VStack(alignment:.leading,spacing:0) { HStack(spacing:12){LogoView(size:48);VStack(alignment:.leading){Text("Mac AI Cleaner").font(.title3.bold());Text("安全分析 · 原生 macOS").font(.caption).foregroundStyle(.secondary)};Spacer();Button(action:settingsAction){Image(systemName:"gearshape").font(.title3)}.buttonStyle(.plain).foregroundStyle(active == "settings" ? .blue : .secondary).help("设置")}.padding(.bottom,24); NavButton(title:scanning ? "扫描进行中…":"安全扫描",icon:scanning ? "arrow.triangle.2.circlepath":"viewfinder",active:active == "scan",action:action).disabled(scanning); NavButton(title:"大文件排序",icon:"arrow.up.arrow.down.circle",active:active == "large",action:largeAction); NavButton(title:"内存监控",icon:"memorychip",active:active == "memory",action:memoryAction); HStack(spacing:8){Circle().fill(scanning ? .orange:.green).frame(width:8,height:8);Text(scanning ? "扫描详情在右侧查看" : status).font(.caption).foregroundStyle(.secondary).lineLimit(2)}.padding(.vertical,12); Divider().padding(.vertical,12); Label("扫描概览",systemImage:"chart.bar.xaxis").font(.headline); if let report { VStack(alignment:.leading,spacing:10){SideStat(title:"发现工具",value:"\(report.detectedTools)");SideStat(title:"已分析数据",value:ByteCountFormatter.string(fromByteCount:report.totalBytes,countStyle:.file));SideStat(title:"保护项目",value:"\(report.findings.filter{$0.risk == .protected}.count)")}.padding(.top,12)}; Spacer(); Label("隐私优先",systemImage:"lock.shield.fill").font(.caption.bold()).foregroundStyle(.blue); Text("只读取元数据，不上传文件内容；当前版本不会移动或删除文件。").font(.caption2).foregroundStyle(.secondary).padding(.top,4) }.padding(24).frame(minWidth:270,idealWidth:290,maxWidth:320,alignment:.leading) }
}
struct NavButton: View { let title:String; let icon:String; let active:Bool; let action:()->Void; var body:some View { Button(action:action){Label(title,systemImage:icon).frame(maxWidth:.infinity,alignment:.leading)}.buttonStyle(.plain).padding(.vertical,10).padding(.horizontal,12).background(active ? Color.accentColor.opacity(0.14) : .clear,in:RoundedRectangle(cornerRadius:9)).foregroundStyle(active ? Color.accentColor : .primary).contentShape(Rectangle()) } }
struct LogoView: View { let size: CGFloat; var body: some View { if let url = Bundle.main.url(forResource: "MacAICleanerLogo", withExtension: "png"), let image = NSImage(contentsOf: url) { Image(nsImage: image).resizable().scaledToFit().frame(width:size,height:size).clipShape(RoundedRectangle(cornerRadius:size * 0.22)) } else { Image(systemName:"sparkles.rectangle.stack.fill").font(.system(size:size * 0.55)).foregroundStyle(.blue) } } }
struct SideStat:View {let title:String;let value:String;var body:some View{HStack{Text(title).foregroundStyle(.secondary);Spacer();Text(value).bold()}}}
struct Dashboard: View { let report:ScanReport; @State private var query=""; @State private var category="全部类别"; @State private var risk="全部风险"; @State private var selected:Finding?
 var categories:[String]{["全部类别"]+Array(Set(report.findings.map(\.category))).sorted()}; var filtered:[Finding]{report.findings.filter{(query.isEmpty || $0.tool.localizedCaseInsensitiveContains(query) || $0.path.localizedCaseInsensitiveContains(query)) && (category=="全部类别" || $0.category==category) && (risk=="全部风险" || $0.risk.rawValue == String(risk.last!))}}
 var body:some View{VStack(alignment:.leading,spacing:20){HStack(alignment:.top){VStack(alignment:.leading,spacing:5){Text("扫描结果").font(.system(size:32,weight:.bold,design:.rounded));Text("规则 \(report.ruleVersion)  ·  \(report.date.formatted(date:.abbreviated,time:.shortened))").font(.caption).foregroundStyle(.secondary)};Spacer();Button{export()}label:{Label("导出脱敏报告",systemImage:"square.and.arrow.up")}.buttonStyle(.bordered).controlSize(.large)};HStack(spacing:12){Metric(title:"分析数据",value:ByteCountFormatter.string(fromByteCount:report.totalBytes,countStyle:.file),icon:"internaldrive.fill",color:.blue);Metric(title:"发现工具",value:"\(report.detectedTools)",icon:"wand.and.stars",color:.purple);Metric(title:"保护项目",value:"\(report.findings.filter{$0.risk == .protected}.count)",icon:"lock.shield.fill",color:.green);Metric(title:"需要复核",value:"\(report.findings.filter{$0.risk == .review}.count)",icon:"exclamationmark.triangle.fill",color:.orange)};HStack{Image(systemName:"info.circle.fill").foregroundStyle(.blue);Text("安全边界：结果仅供分析，所有项目默认保护。点击条目查看用途、影响和恢复说明。").font(.callout);Spacer()}.padding(14).background(.blue.opacity(0.08),in:RoundedRectangle(cornerRadius:12));HStack{TextField("搜索工具或路径",text:$query).textFieldStyle(.roundedBorder).frame(maxWidth:260);Picker("类别",selection:$category){ForEach(categories,id:\.self){Text($0).tag($0)}}.frame(width:160);Picker("风险",selection:$risk){Text("全部风险").tag("全部风险");Text("B · 需复核").tag("B · 需复核");Text("C · 保护").tag("C · 保护")}.frame(width:145);Spacer();Text("\(filtered.count) 项").font(.caption).foregroundStyle(.secondary)};if filtered.isEmpty{ContentUnavailableView("没有匹配项目",systemImage:"line.3.horizontal.decrease.circle",description:Text("调整搜索或筛选条件。"))}else{List(filtered){f in FindingRow(finding:f).contentShape(Rectangle()).onTapGesture{selected=f}.listRowSeparator(.hidden).listRowBackground(Color.clear)}.listStyle(.plain)}}.padding(28).overlay { if let finding = selected { ZStack { Color.black.opacity(0.28).ignoresSafeArea().onTapGesture { selected = nil }; FindingDetail(finding:finding, dismiss:{ selected = nil }).background(.background,in:RoundedRectangle(cornerRadius:18)).shadow(color:.black.opacity(0.2),radius:30) }.transition(.opacity) } }.animation(.easeOut(duration:0.16),value:selected?.id) }
 private func export(){guard let data=try? JSONEncoder().encode(report)else{return};let panel=NSSavePanel();panel.nameFieldStringValue="mac-ai-cleaner-report.json";panel.begin{if $0 == .OK,let url=panel.url{try? data.write(to:url)}}}
}
struct Metric:View{let title:String;let value:String;let icon:String;let color:Color;var body:some View{HStack(spacing:12){Image(systemName:icon).font(.title3).foregroundStyle(color).frame(width:32,height:32).background(color.opacity(0.12),in:RoundedRectangle(cornerRadius:8));VStack(alignment:.leading){Text(title).font(.caption).foregroundStyle(.secondary);Text(value).font(.title3.bold())}}.frame(maxWidth:.infinity,alignment:.leading).padding(14).background(.background,in:RoundedRectangle(cornerRadius:12)).overlay(RoundedRectangle(cornerRadius:12).stroke(.quaternary))}}
struct FindingRow:View{let finding:Finding;var body:some View{HStack(spacing:14){Image(systemName:finding.risk == .protected ? "lock.shield.fill":"exclamationmark.triangle.fill").font(.title3).foregroundStyle(finding.risk == .protected ? .blue:.orange).frame(width:36);VStack(alignment:.leading,spacing:4){HStack{Text(finding.tool).font(.headline);Text(finding.category).font(.caption).padding(.horizontal,7).padding(.vertical,3).background(.quaternary,in:Capsule())};Text(finding.path).font(.caption).foregroundStyle(.secondary).lineLimit(1);Text(finding.reason).font(.caption2).foregroundStyle(.secondary).lineLimit(1)};Spacer();VStack(alignment:.trailing,spacing:4){Text(ByteCountFormatter.string(fromByteCount:finding.bytes,countStyle:.file)).font(.headline);Text("风险 \(finding.risk.rawValue) · \(finding.files) 文件").font(.caption).foregroundStyle(.secondary)};Image(systemName:"chevron.right").font(.caption).foregroundStyle(.tertiary)}.padding(14).background(.background,in:RoundedRectangle(cornerRadius:12)).overlay(RoundedRectangle(cornerRadius:12).stroke(.quaternary))}}
struct FindingDetail: View { let finding: Finding; let dismiss: () -> Void; @State private var confirm = false; @State private var message = ""
 var body: some View { VStack(alignment:.leading,spacing:18) { HStack { Image(systemName:finding.risk == .protected ? "lock.shield.fill":"exclamationmark.triangle.fill").foregroundStyle(finding.risk == .protected ? .blue:.orange); Text(finding.tool).font(.title2.bold()); Spacer(); Text("风险 \(finding.risk.rawValue)").font(.headline); Button(action:dismiss){Image(systemName:"xmark.circle.fill").font(.title2).foregroundStyle(.secondary)}.buttonStyle(.plain) }; Text(finding.path).font(.caption).textSelection(.enabled); HStack { Button { NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath:finding.path)]) } label: { Label("在访达中显示",systemImage:"folder") }.buttonStyle(.bordered); Button { NSPasteboard.general.clearContents(); NSPasteboard.general.setString(finding.path,forType:.string) } label: { Label("复制路径",systemImage:"doc.on.doc") }.buttonStyle(.bordered); if finding.cleanable { Button { confirm = true } label: { Label("移到废纸篓",systemImage:"trash") }.buttonStyle(.borderedProminent).tint(.orange) } }; Block(title:"为什么出现",text:finding.reason); Block(title:"可能影响",text:finding.impact); Block(title:"恢复条件",text:finding.recovery); if !message.isEmpty { Text(message).font(.caption).foregroundStyle(.orange) }; Spacer() }.padding(26).frame(width:560,height:390).onExitCommand(perform:dismiss).alert("确认移到废纸篓",isPresented:$confirm){Button("取消",role:.cancel){};Button("确认",role:.destructive){do{try CleanupExecutor.moveFindingToTrash(finding,home:FileManager.default.homeDirectoryForCurrentUser);message="已移到废纸篓"}catch{message=error.localizedDescription}}}message:{Text("只处理已通过缓存规则的项目，文件可从废纸篓恢复。")}} }

struct Block:View{let title:String;let text:String;var body:some View{VStack(alignment:.leading,spacing:4){Text(title).font(.caption.bold()).foregroundStyle(.secondary);Text(text).font(.callout)}}}
struct EmptyState:View{let action:()->Void;var body:some View{VStack(spacing:18){Image(systemName:"sparkles.rectangle.stack").font(.system(size:62)).foregroundStyle(.blue.gradient);Text("先做一次安全扫描").font(.system(size:30,weight:.bold,design:.rounded));Text("识别 AI 工具和开发环境的数据占用，解释每项风险。\n扫描只读取元数据，不会删除或上传任何文件。").multilineTextAlignment(.center).foregroundStyle(.secondary);Button("开始只读扫描",action:action).buttonStyle(.borderedProminent).controlSize(.large)}}}

struct MemoryView: View {
 @State private var snapshot: MemorySnapshot?; @State private var loading = true; @AppStorage("appLanguageEnglish") private var english = false
 var body: some View {
  VStack(alignment:.leading,spacing:18) {
   HStack { VStack(alignment:.leading,spacing:4) { Text(english ? "Memory Monitor" : "内存监控").font(.system(size:32,weight:.bold,design:.rounded)); Text(english ? "System memory, pressure and process usage" : "系统内存、压力和进程占用").foregroundStyle(.secondary) }; Spacer(); if let snapshot { Text(english ? "Updated " : "更新于 ") + Text(snapshot.date.formatted(date:.omitted,time:.shortened)).foregroundStyle(.secondary) }; Button { load() } label:{Label(english ? "Refresh":"刷新",systemImage:"arrow.clockwise")}.buttonStyle(.bordered) }
   if loading { ProgressView(english ? "Reading memory…":"正在读取内存…").frame(maxWidth:.infinity,maxHeight:.infinity) } else if let snapshot {
    HStack(spacing:10) { MemoryMetric(title:english ? "Used":"已使用",value:format(snapshot.usedBytes),icon:"memorychip",color:.blue); MemoryMetric(title:english ? "Available":"可用",value:format(snapshot.availableBytes),icon:"gauge.with.dots.needle.67percent",color:.green); MemoryMetric(title:english ? "Active":"活跃",value:format(snapshot.activeBytes),icon:"waveform.path.ecg",color:.orange); MemoryMetric(title:english ? "Wired":"常驻",value:format(snapshot.wiredBytes),icon:"pin.fill",color:.purple); MemoryMetric(title:english ? "Compressed":"压缩",value:format(snapshot.compressedBytes),icon:"archivebox.fill",color:.pink) }
    HStack { Text(english ? "Memory pressure":"内存压力").font(.headline); ProgressView(value:snapshot.usedRatio).tint(snapshot.usedRatio > 0.9 ? .red : snapshot.usedRatio > 0.75 ? .orange : .green); Text(snapshot.pressure).foregroundStyle(snapshot.usedRatio > 0.9 ? .red : .secondary) }.padding(14).background(.background,in:RoundedRectangle(cornerRadius:12)).overlay(RoundedRectangle(cornerRadius:12).stroke(.quaternary))
    HStack { Text(english ? "Running processes":"运行中的程序").font(.title2.bold()); Spacer(); Text("\(snapshot.processes.count) 个 · 按常驻内存排序").font(.caption).foregroundStyle(.secondary) }
    List(snapshot.processes) { p in HStack(spacing:12) { Image(systemName:"app.fill").foregroundStyle(.secondary).frame(width:24); VStack(alignment:.leading,spacing:3){Text(p.name).font(.headline);Text("PID \(p.id) · \(p.threads) threads").font(.caption).foregroundStyle(.secondary)}; Spacer(); VStack(alignment:.trailing,spacing:3){Text(format(p.bytes)).font(.headline).monospacedDigit();Text("虚拟 \(format(p.virtualBytes))").font(.caption).foregroundStyle(.secondary)} }.padding(.vertical,4) }.listStyle(.plain)
    Text(english ? "RSS is resident memory. Some system processes may be unavailable without macOS permission; unavailable processes are omitted rather than shown as zero.":"RSS 是进程常驻内存。部分系统进程受 macOS 权限保护，无法读取时会省略，不会显示为 0。").font(.caption).foregroundStyle(.secondary)
   }
  }.padding(28).task { load() }
 }
 private func format(_ bytes: UInt64) -> String { ByteCountFormatter.string(fromByteCount:Int64(bytes),countStyle:.memory) }
 private func load() { loading = true; Task.detached { let value = MemoryMonitor.snapshot(); await MainActor.run { snapshot = value; loading = false } } }
}
struct MemoryMetric: View { let title:String; let value:String; let icon:String; let color:Color; var body:some View { HStack(spacing:9){Image(systemName:icon).foregroundStyle(color);VStack(alignment:.leading,spacing:2){Text(title).font(.caption).foregroundStyle(.secondary);Text(value).font(.headline).monospacedDigit()}}.frame(maxWidth:.infinity,alignment:.leading).padding(12).background(.background,in:RoundedRectangle(cornerRadius:10)).overlay(RoundedRectangle(cornerRadius:10).stroke(.quaternary)) } }

struct Dashboard2: View {
 let report: ScanReport
 @State private var tab = 0
 @State private var largeItems: [LargeItem] = []
 @State private var selected: LargeItem?
 @State private var pendingCleanup: [LargeItem] = []
 @State private var scanningLarge = false
 @State private var confirmCleanup = false
 var body: some View {
  VStack(alignment: .leading, spacing: 18) {
   HStack { VStack(alignment: .leading, spacing: 4) { Text(tab == 0 ? "扫描结果" : "大文件排序").font(.system(size: 32, weight: .bold, design: .rounded)); Text(tab == 0 ? "AI 工具与开发目录" : "按文件大小排序 · 只读取元数据").foregroundStyle(.secondary) }; Spacer(); Picker("视图", selection: $tab) { Text("AI 工具").tag(0); Text("大文件").tag(1) }.pickerStyle(.segmented).frame(width: 190) }
   if tab == 0 { FindingList(report: report) } else { LargeFilesPanel(items: largeItems, scanning: scanningLarge, scan: scanLarge, cleanup: { picked in pendingCleanup = picked; confirmCleanup = true }) }
  }.padding(28).alert("移到废纸篓", isPresented: $confirmCleanup) { Button("取消", role: .cancel) {}; Button("确认清理", role: .destructive) { cleanupSelected() } } message: { Text("将处理 \(pendingCleanup.count) 个缓存候选。文件会进入废纸篓，可恢复；系统、项目、会话和未知文件不会被处理。") }
 }
 private func scanLarge() { guard !scanningLarge else { return }; scanningLarge = true; Task.detached { let result = Scanner().scanLargeItems(minBytes: 10 * 1024 * 1024); await MainActor.run { largeItems = result; scanningLarge = false } } }
 private func cleanupSelected() { var moved = Set<String>(); for item in pendingCleanup { if (try? CleanupExecutor.moveToTrash(item, home: FileManager.default.homeDirectoryForCurrentUser)) != nil { moved.insert(item.id) } }; largeItems.removeAll { moved.contains($0.id) }; pendingCleanup = [] }
}
struct FindingList: View { let report: ScanReport; var body: some View { List(report.findings) { f in FindingRow(finding: f).listRowSeparator(.hidden).listRowBackground(Color.clear) }.listStyle(.plain) } }
struct LargeFilesPanel: View { let items: [LargeItem]; let scanning: Bool; let scan: () -> Void; let cleanup: ([LargeItem]) -> Void; @State private var checked = Set<String>(); @State private var phase = "准备扫描"; @State private var usage = Scanner().diskUsage()
 var body: some View { VStack(alignment: .leading, spacing: 16) { HStack { VStack(alignment:.leading){ Text("磁盘空间").font(.title2.bold()); Text("系统磁盘使用情况").foregroundStyle(.secondary) }; Spacer(); StorageCard(usage: usage); Button(scanning ? "扫描中…" : "扫描大文件", action: scan).buttonStyle(.bordered).disabled(scanning) }; if scanning { ProgressView().progressViewStyle(.linear); Text("正在扫描目录：Library/Caches、.cache、.npm、Downloads（不会访问通讯录或日历）").font(.caption).foregroundStyle(.secondary) }; HStack { Text("按大小排序").font(.headline); Spacer(); Text("已选 \(checked.count) 项").font(.caption).foregroundStyle(.secondary); if !checked.isEmpty { Button { cleanup(items.filter { checked.contains($0.id) }) } label: { Label("移到废纸篓", systemImage:"trash") }.buttonStyle(.borderedProminent).tint(.orange) } }; if items.isEmpty { ContentUnavailableView("还没有大文件结果", systemImage: "externaldrive", description: Text("点击“扫描大文件”开始，默认阈值为 10 MB。")) } else { List(items) { item in HStack { Toggle("", isOn: Binding(get:{checked.contains(item.id)},set:{on in if on {checked.insert(item.id)} else {checked.remove(item.id)}})).labelsHidden(); Image(systemName: item.risk == .review ? "trash" : "lock.shield").foregroundStyle(item.risk == .review ? .orange : .blue); VStack(alignment: .leading) { Text(item.name).font(.headline); Text(item.path).font(.caption).foregroundStyle(.secondary).lineLimit(1); Text(item.reason).font(.caption2).foregroundStyle(.secondary) }; Spacer(); Text(ByteCountFormatter.string(fromByteCount: item.bytes, countStyle: .file)).font(.headline); Button { NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath:item.path)]) } label: { Image(systemName:"folder") }.buttonStyle(.borderless).help("在访达中显示"); Button { NSPasteboard.general.clearContents(); NSPasteboard.general.setString(item.path, forType:.string) } label: { Image(systemName:"doc.on.doc") }.buttonStyle(.borderless).help("复制路径"); Text(item.risk == .review ? "可移入废纸篓" : "已保护").font(.caption).foregroundStyle(item.risk == .review ? .orange : .secondary) }.listRowSeparator(.hidden).listRowBackground(Color.clear) }.listStyle(.plain) } }.onAppear { usage = Scanner().diskUsage(); if items.isEmpty { scan() } } }
}
struct StorageCard: View { let usage: DiskUsage; var body: some View { VStack(alignment:.leading,spacing:12){ HStack{Text("Macintosh HD").font(.title3.bold());Spacer();Text("\(ByteCountFormatter.string(fromByteCount:usage.usedBytes,countStyle:.file))/\(ByteCountFormatter.string(fromByteCount:usage.totalBytes,countStyle:.file)) 已使用").foregroundStyle(.secondary) }; HStack(spacing:1){ForEach([Color.red,Color.orange,Color.yellow,Color.green,Color.gray,Color.secondary],id:\.self){ color in color.frame(maxWidth:.infinity).frame(height:26) }}.clipShape(RoundedRectangle(cornerRadius:6)); HStack(spacing:14){Legend(color:.red,text:"文稿");Legend(color:.orange,text:"应用程序");Legend(color:.yellow,text:"开发者");Legend(color:.green,text:"其他用户与共享");Legend(color:.gray,text:"系统数据");Legend(color:.secondary,text:"macOS")}; Text("分类将在扫描完成后根据实际结果细化。").font(.caption2).foregroundStyle(.secondary) }.padding(18).background(.background,in:RoundedRectangle(cornerRadius:14)).overlay(RoundedRectangle(cornerRadius:14).stroke(.quaternary)) } }
struct Legend: View { let color: Color; let text: String; var body: some View { HStack(spacing:5){Circle().fill(color).frame(width:10,height:10);Text(text).font(.caption).foregroundStyle(.secondary)} } }

struct LargeFilesStandalone: View {
 @State private var items: [LargeItem] = []; @State private var scanning = false; @State private var selected: LargeItem?; @State private var pending: [LargeItem] = []; @State private var confirm = false
 var body: some View { LargeFilesPanel(items: items, scanning: scanning, scan: scan, cleanup: { picked in pending = picked; confirm = true }).padding(28).alert("移到废纸篓", isPresented: $confirm) { Button("取消", role: .cancel) {}; Button("确认清理", role: .destructive) { clean() } } message: { Text("将处理 \(pending.count) 个缓存候选，文件会进入废纸篓。") }.onAppear { scan() } }
 private func scan() { guard !scanning else { return }; scanning = true; Task.detached { let value = Scanner().scanLargeItems(minBytes: 10 * 1024 * 1024); await MainActor.run { items = value; scanning = false } } }
 private func clean() { var moved = Set<String>(); for item in pending { if (try? CleanupExecutor.moveToTrash(item, home: FileManager.default.homeDirectoryForCurrentUser)) != nil { moved.insert(item.id) } }; items.removeAll { moved.contains($0.id) }; pending = []; selected = nil }
}

struct ScanProgressView: View { let tool: String; let status: String; let start: () -> Void; var body: some View { ScrollView { VStack(alignment:.leading,spacing:22){ StorageCard(usage: Scanner().diskUsage()); HStack{Image(systemName:tool.isEmpty ? "sparkles.rectangle.stack.fill":"arrow.triangle.2.circlepath").font(.system(size:34)).foregroundStyle(.blue);VStack(alignment:.leading){Text(tool.isEmpty ? "准备安全扫描":"正在安全扫描").font(.title2.bold());Text(status).foregroundStyle(.secondary)};Spacer();if tool.isEmpty{Button("开始扫描",action:start).buttonStyle(.borderedProminent).controlSize(.large)}else{ProgressView().controlSize(.large)}};Text("只读取文件元数据，不会删除或上传内容。").font(.caption).foregroundStyle(.secondary)}.padding(32).frame(maxWidth:.infinity,alignment:.leading)}} }
struct SettingsView: View { @AppStorage("appLanguageEnglish") private var english = false; var body: some View { Form { Section("语言 / Language") { Picker("界面语言",selection:$english){Text("中文").tag(false);Text("English").tag(true)}.pickerStyle(.segmented) }; Section("安全") { Label("只读扫描默认开启",systemImage:"lock.shield"); Text("清理只允许经策略审核的缓存进入废纸篓，系统和未知文件不会被处理。").font(.caption).foregroundStyle(.secondary) } }.formStyle(.grouped).frame(maxWidth:600).padding(28) } }
